import type { ProgressSegments } from '~/components/ui/composedProgress/index';

export function getProgressValue(current: number, total: number) {
  const value = total > 0 ? (current / total) * 100 : 0;
  return Math.min(value, 100);
}

export function normalizeSegments(segments: ProgressSegments[], max = 100) {
  const total = segments.reduce((a, b) => a + b.value, 0);
  segments = segments.map((segment) => ({ ...segment, value: (segment.value * 100) / max }));
  if (total <= max || total === 0) return segments;
  const factor = max / total;
  return segments.map((segment) => ({ ...segment, value: segment.value * factor }));
}
